"""Browser QA for HTML generated by the real Windows app's synthetic smoke run."""
import sys
from pathlib import Path

from playwright.sync_api import sync_playwright


def main():
    directory = Path(sys.argv[1]).resolve()
    errors, network = [], []
    with sync_playwright() as automation:
        browser = automation.chromium.launch()
        page = browser.new_page(viewport={"width": 1360, "height": 1000})
        page.on("pageerror", lambda error: errors.append(str(error)))
        page.on("request", lambda request: network.append(request.url) if not request.url.startswith("file:") else None)
        for name in ("demo", "mismatched", "no-capture"):
            page.goto((directory / ("report-" + name + ".html")).as_uri())
            assert page.get_by_role("heading", name="A clearer picture of your laptop.").is_visible()
            assert page.get_by_text("SYNTHETIC DEMO", exact=True).is_visible()
            assert page.locator("script").count() == 0
            if name == "demo":
                assert page.get_by_text("-5.0 pp", exact=True).count() == 1
                assert page.get_by_role("table", name="Aggregate history, up to 12 results").is_visible()
            elif name == "mismatched":
                assert page.get_by_text("Comparison unavailable", exact=True).is_visible()
                assert page.get_by_role("table", name="Observed differences, not proof of improvement").count() == 0
            else:
                assert "No CPU result is included" in page.locator("#performance").inner_text()
                assert "Device snapshot unavailable" in page.locator("#device").inner_text()
            for width, label in ((1360, "desktop"), (390, "mobile")):
                page.set_viewport_size({"width": width, "height": 1000})
                assert page.evaluate("document.documentElement.scrollWidth <= innerWidth"), (name, label)
                page.screenshot(path=str(directory / ("report-" + name + "-" + label + ".png")), full_page=True)
            page.emulate_media(media="print")
            page.pdf(path=str(directory / ("report-" + name + "-print.pdf")), format="A4", print_background=True)
            page.emulate_media(media="screen")
        assert not errors, errors
        assert not network, network
        browser.close()
    print("PASS: compatible/mismatched/missing reports, desktop/mobile layout, print PDFs, no scripts or remote requests.")


if __name__ == "__main__":
    main()
